const CARD_VERSION="0.2.4";
const FLOORPLAN="data:image/png;base64,";
class AutoFloorplanControls extends HTMLElement{
 setConfig(c){this.config=c||{};this.sel=this.sel||"lounge";if(!this.shadowRoot)this.attachShadow({mode:"open"});}
 set hass(h){this._hass=h;this.render();}
 getCardSize(){return 10} static getStubConfig(){return{title:"Lights & Plugs"}}
 zones(){return[
  ["kids","Bed 2 (Kids)",["kids room","bed 2"],10,21],["nursery","Bed 3 (Nursery)",["nursery","bed 3"],10,45],
  ["master","Bed 1 (Master)",["master bedroom","bed 1"],10,68],["bathroom","Bathroom",["bathroom"],27,22],
  ["laundry","Laundry",["laundry"],39,24],["kitchen","Kitchen",["kitchen"],57,24],
  ["lounge","Lounge",["lounge","living room"],37,54],["dining","Dining",["dining","dining room"],57,47],
  ["porch","Porch",["porch","entry"],43,72],["garage","Garage",["garage"],68,51],["shed","Shed",["shed"],72,13]
 ]}
 areaName(eid){const er=this._hass?.entities?.[eid];const aid=er?.area_id||this._hass?.devices?.[er?.device_id]?.area_id;return (this._hass?.areas?.[aid]?.name||"").toLowerCase()}
 entities(zone){const aliases=this.zones().find(z=>z[0]===zone)?.[2]||[];return Object.values(this._hass.states).filter(s=>["light","switch"].includes(s.entity_id.split('.')[0])&&aliases.some(a=>this.areaName(s.entity_id).includes(a))).sort((a,b)=>(a.attributes.friendly_name||a.entity_id).localeCompare(b.attributes.friendly_name||b.entity_id))}
 toggle(e){this._hass.callService(e.entity_id.split('.')[0],"toggle",{entity_id:e.entity_id})}
 more(eid){const ev=new Event("hass-more-info",{bubbles:true,composed:true});ev.detail={entityId:eid};this.dispatchEvent(ev)}
 render(){if(!this._hass)return;const zones=this.zones(), z=this.sel, ents=this.entities(z), label=zones.find(x=>x[0]===z)?.[1]||z;
 this.shadowRoot.innerHTML=`<style>:host{display:block}.c{background:#0c1823;color:#eef7ff;overflow:hidden}.head{padding:16px 18px;font-size:24px;font-weight:700}.sub{font-size:13px;color:#9fb1c1;font-weight:400}.body{display:grid;grid-template-columns:minmax(0,3fr) minmax(280px,1fr);gap:12px;padding:0 14px 14px}.plan{position:relative;border-radius:12px;overflow:hidden;background:#07131d}.plan img{width:100%;display:block}.hot{position:absolute;transform:translate(-50%,-50%);border:1px solid #3b647d;background:#102536e8;color:#fff;border-radius:8px;padding:6px 9px;cursor:pointer;font-weight:700}.hot.sel{outline:2px solid #28b8ff}.panel{background:#10202e;border:1px solid #263c4e;border-radius:12px;padding:14px}.row{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;background:#142838;border-radius:9px;padding:10px;margin:8px 0}.row button{border:1px solid #3c5b70;background:#193247;color:white;border-radius:7px;padding:7px 10px}.slider{grid-column:1/-1;width:100%}.empty{color:#9fb1c1}.rooms{display:flex;gap:7px;flex-wrap:wrap;padding:0 14px 14px}.rooms button{background:#10202e;color:white;border:1px solid #263c4e;border-radius:8px;padding:8px 10px}.rooms button.sel{border-color:#28b8ff}@media(max-width:900px){.body{grid-template-columns:1fr}}</style><ha-card class="c"><div class="head">💡 ${this.config.title||"Lights & Plugs"}<div class="sub">Automatic HA Area discovery · v${CARD_VERSION}</div></div><div class="body"><div class="plan"><img src="${FLOORPLAN}">${zones.map(x=>`<button class="hot ${z===x[0]?'sel':''}" data-z="${x[0]}" style="left:${x[3]}%;top:${x[4]}%">${x[1]}</button>`).join('')}</div><div class="panel"><h2>${label}</h2><div class="sub">Lights, plugs and switches assigned to this Home Assistant Area</div>${ents.length?ents.map((e,i)=>{const on=e.state==='on',bright=e.attributes.brightness;return `<div class="row"><span>${e.attributes.friendly_name||e.entity_id}<br><small class="sub">${on?'ON':'OFF'}</small></span><button data-t="${i}">${on?'Turn off':'Turn on'}</button>${e.entity_id.startsWith('light.')&&bright!==undefined?`<input class="slider" data-b="${i}" type="range" min="1" max="255" value="${bright||1}">`:''}</div>`}).join(''):`<p class="empty">No light/switch entities found in this HA Area.</p>`}</div></div><div class="rooms">${zones.map(x=>`<button data-z="${x[0]}" class="${z===x[0]?'sel':''}">${x[1]} · ${this.entities(x[0]).filter(e=>e.state==='on').length} on</button>`).join('')}</div></ha-card>`;
 this.shadowRoot.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{this.sel=b.dataset.z;this.render()});
 this.shadowRoot.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>this.toggle(ents[+b.dataset.t]));
 this.shadowRoot.querySelectorAll('[data-b]').forEach(r=>r.onchange=()=>this._hass.callService('light','turn_on',{entity_id:ents[+r.dataset.b].entity_id,brightness:+r.value}));
 }}
customElements.define("auto-floorplan-controls",AutoFloorplanControls);window.customCards=window.customCards||[];window.customCards.push({type:"auto-floorplan-controls",name:"Lights & Plugs Floorplan",description:"Interactive floorplan controls using Home Assistant Areas"});
